import React from "react";
import './Home.css';
import { Container } from "react-bootstrap";

const Home=()=>{

    // i realize i should map locations and date to avoid css in all div 
    const concerts=[
        {
            id:1,
            date:"JULY",
            place:"DELHI",
            location:"BATRA THEATER "

        },
      
        {
            id:2,
            date:"JULY 20",
            place:"GHAZIABAD",
            location:"OPULANT MALL "

        },
        {
            id:3,
            date:"JULY 24",
            place:"LUCKNOW",
            location:"CHAR BAGH THEATER"

        },
        {
            id:4,
            date:"AUG 5",
            place:"NOIDA",
            location:"GIP MALL "

        },
      
    ]

       const showConcert=concerts.map((item)=>(
        <div key={item.id} className="div1">
        <div> <span>{item.date}</span></div>
        <div><span>{item.place}</span></div>
        <div><span>{item.location} </span></div>
        <div> <button>BUY TICKETS</button></div>
       
    </div>
   
       ))
    return(
        <>
        <div className="home">
         <div className="button">
            <button>Get our Latest Album</button>
         </div>

         <div className="play"> 
            <button>Play</button>
         </div>
        </div>

        <div ><h2>Tours</h2></div>
        <Container></Container>
        <div className="content">
       {showConcert}
       </div>
        </>
    )
}
export default Home;
